import { join } from 'node:path';
import { test, expect, makeIdToken, signedIn } from './fixtures';
import { evaluateResilienceIq } from '../../packages/engine-core/src/accelerators/resilience-iq/evaluate';

// Resilience IQ reads its API from cost-iq-runtime-config.js and its question bank from the hosted copy;
// both are generated by the Amplify build, so the tests serve them.
const RESILIENCE_API = 'https://resilience-test.execute-api.ap-south-1.amazonaws.com';
const EVALUATE = '/api/evaluate/resilience-iq';
const BANK = join(process.cwd(), 'resilience-iq/knowledge/question-bank.json');

const permitted = (token: string, refreshToken?: string) => ({
  email: 'consultant@ltm.com',
  token,
  refreshToken,
  role: 'advisor_viewer',
  permissions: { take: ['resilience-iq'], view: ['resilience-iq'] }
});

test.describe('Resilience IQ', () => {
  test.beforeEach(async ({ context, world }) => {
    await context.route(/\/cost-iq-runtime-config\.js$/, route => route.fulfill({
      contentType: 'application/javascript',
      body: `window.COST_IQ_API='${RESILIENCE_API}';window.RESILIENCE_IQ_API='${RESILIENCE_API}';`
    }));
    await context.route(/\/resilience-iq\/knowledge\/question-bank\.json$/, route => route.fulfill({ path: BANK, contentType: 'application/json' }));
    // Like the Lambda: the real engine scores whatever the page sends.
    world.on('POST', EVALUATE, ({ body }) => ({ body: { ok: true, data: evaluateResilienceIq(body.answers || {}) } }));
  });

  test('a signed-out user is sent to sign in', async ({ page }) => {
    await page.goto('/resilience-iq');
    await expect(page).toHaveURL(/\/\?require_login=1&redirect=%2Fresilience-iq/);
  });

  test('a user without Resilience IQ access is turned away', async ({ page, context }) => {
    await signedIn(context, { ...permitted(makeIdToken('consultant@ltm.com')), permissions: { take: ['cloud-iq'], view: ['cloud-iq'] } });
    await page.goto('/resilience-iq');
    await expect(page).toHaveURL(/\/$/);
  });

  test('a permitted user sees the assessment setup under the LTM Vantage brand, with no errors', async ({ page, context, world }) => {
    await signedIn(context, permitted(makeIdToken('consultant@ltm.com')));
    await page.goto('/resilience-iq');
    await expect(page.locator('#app')).toContainText('LTM VANTAGE · RESILIENCE IQ');
    await expect(page).toHaveTitle(/LTM Vantage/);
    expect(world.pageErrors).toEqual([]);
    expect(world.missingFiles).toEqual([]);
  });

  test('an expired token is renewed and the evaluation is sent with it and scored by the engine', async ({ page, context, world }) => {
    await signedIn(context, permitted(makeIdToken('consultant@ltm.com', -60), 'refresh-consultant@ltm.com'));
    await page.goto('/resilience-iq');
    await expect(page).toHaveURL(/\/resilience-iq$/);

    const out = await page.evaluate(async (path) => {
      const res = await (window as any).authFetch((window as any).RESILIENCE_IQ_API + path, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ answers: { 'EX-03': 'Unknown', 'EX-04': 'Unknown' } })
      });
      return { status: res.status, body: await res.json() };
    }, EVALUATE);

    expect(world.refreshCount).toBe(1);
    expect(world.calls).toContain(`POST ${EVALUATE} auth=bearer`);
    expect(out.status).toBe(200);
    expect(out.body.data.status).toBe('requirements_incomplete');
    expect(out.body.data.evidenceRequests).toContain('BIA');
  });
});
